from email import policy
from email.parser import BytesParser
from pathlib import Path
for src,out in [('documents/draft-3-instruction-email.eml','extracted/instruction-email.txt'),('documents/business-negotiation-email-thread-may-5-6.eml','extracted/business-thread.txt'),('documents/legal-negotiation-email-thread-may-7-9.eml','extracted/legal-thread.txt')]:
    msg=BytesParser(policy=policy.default).parsebytes(Path(src).read_bytes())
    parts=[]
    parts.append(f"Subject: {msg.get('Subject','')}\nFrom: {msg.get('From','')}\nTo: {msg.get('To','')}\nDate: {msg.get('Date','')}\n")
    if msg.is_multipart():
        for p in msg.walk():
            if p.get_content_type()=='text/plain':
                parts.append(p.get_content())
    else:
        parts.append(msg.get_content())
    Path(out).write_text('\n\n'.join(parts), encoding='utf-8')
PY","description":"Convert email references to plain text"}

