from zipfile import ZipFile, ZIP_DEFLATED
from lxml import etree
from pathlib import Path
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
ns={'w':W}
src=Path('documents/technova-ai-vendor-agreement-draft-2-redline.docx')
out=Path('extracted/draft2-clean.docx')
with ZipFile(src) as zin:
    data={n:zin.read(n) for n in zin.namelist()}
root=etree.fromstring(data['word/document.xml'])
for el in list(root.xpath('.//w:del',namespaces=ns)):
    el.getparent().remove(el)
for el in list(root.xpath('.//w:ins',namespaces=ns)):
    parent=el.getparent(); idx=parent.index(el)
    for child in list(el):
        parent.insert(idx, child); idx+=1
    parent.remove(el)
data['word/document.xml']=etree.tostring(root,xml_declaration=True,encoding='UTF-8',standalone='yes')
with ZipFile(out,'w',ZIP_DEFLATED) as zout:
    for n,b in data.items(): zout.writestr(n,b)

def txt(el):
    return ''.join(el.xpath('.//w:t/text()',namespaces=ns))
body=root.find('.//w:body',ns)
for i,child in enumerate(body):
    if child.tag==f'{{{W}}}p':
        t=txt(child)
        if any(s in t for s in ['Section 5.2','Section 6.1','Section 6.5','Section 9.2','Section 9.3','Section 9.4','Section 10.2','Section 10.3','Section 11.1','Section 12.1','Section 14.1','Section 14.2','EXHIBIT A','EXHIBIT B','EXHIBIT D','EXHIBIT E','Customer-Trained','Data Processing Addendum','Service Credit','Tech E&O','F1','Escrow']):
            print('P',i,repr(t[:300]))
    elif child.tag==f'{{{W}}}tbl':
        print('TABLE',i,repr(txt(child)[:500]))
PY
